# Public API (cm:*)
  @api cm:setContext(newTake)  @ 413-418
      @contract  setContext(nil) clears take+track; setContext(take) derives track via GetMediaItemTrack  @ 411
      @contract  refreshes all persisted caches (transient resets to {}) and fires configChanged {}  @ 412
  @api cm:clearTake()  @ 420-425
  @api cm:boundTake()  @ 428
      @contract  bound take pointer; nil when context is cleared (take/track tiers resolve off empty)  @ 427
  @api cm:boundTrack()  @ 431
      @contract  bound track pointer; nil when context is cleared (track tier resolves off empty)  @ 430
  @api cm:setTrack(newTrack)  @ 433-438
  @api cm:pollUndo()  @ 441
